import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import React from "react";

export const fps = 25;
export const durationInFrames = 750;

const COLORS = {
  accent: "#528FFF",
  light: "#92C0FF",
  muted: "#6B9FFF",
  dark: "#1E52E0",
  bg: "#0F192F",
};

const TRANSITION = 18;

// ─── Scene 1: Credibility Filter ───────────────────────────────────────────

const credibilityFlags = [
  {
    icon: "🔄",
    label: "Multiple Username Changes",
    sublabel: "Recycled or rebranded identities",
    color: "#EF4444",
    badge: "HIGH RISK",
  },
  {
    icon: "⚡",
    label: "New Account · Large Following",
    sublabel: "Suspicious growth pattern",
    color: "#EF4444",
    badge: "HIGH RISK",
  },
  {
    icon: "📍",
    label: "Location Mismatch",
    sublabel: "Claims Berlin · Country says otherwise",
    color: "#F5BC38",
    badge: "REVIEW",
  },
];

const FlagRow: React.FC<{ item: (typeof credibilityFlags)[0]; delay: number }> = ({ item, delay }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const progress = spring({ frame, fps: vfps, delay, config: { damping: 200 } });
  const translateX = interpolate(progress, [0, 1], [-50, 0]);

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 40,
        padding: "32px 48px",
        backgroundColor: "rgba(255,255,255,0.03)",
        border: "1px solid rgba(255,255,255,0.06)",
        borderLeft: `4px solid ${item.color}`,
        borderRadius: 20,
        opacity: progress,
        transform: `translateX(${translateX}px)`,
      }}
    >
      <div style={{ fontSize: 48 }}>{item.icon}</div>
      <div style={{ flex: 1 }}>
        <div style={{ fontSize: 34, fontWeight: 700, color: COLORS.light, marginBottom: 8 }}>
          {item.label}
        </div>
        <div style={{ fontSize: 26, fontWeight: 600, color: COLORS.muted }}>{item.sublabel}</div>
      </div>
      <div
        style={{
          backgroundColor: `${item.color}18`,
          border: `1px solid ${item.color}44`,
          borderRadius: 40,
          padding: "12px 32px",
          fontSize: 22,
          fontWeight: 700,
          color: item.color,
          letterSpacing: "0.14em",
          textTransform: "uppercase" as const,
          whiteSpace: "nowrap" as const,
        }}
      >
        {item.badge}
      </div>
    </div>
  );
};

const profileRows = [
  { field: "Username changes", value: "4×", risk: true },
  { field: "Account age", value: "3 months", risk: true },
  { field: "Followers", value: "284K", risk: false },
  { field: "Declared location", value: "Berlin, DE", risk: false },
  { field: "Country (metadata)", value: "UA", risk: true },
];

const SceneCredibilityFilter: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const titleProgress = spring({ frame, fps: vfps, delay: 5, config: { damping: 200 } });
  const titleY = interpolate(titleProgress, [0, 1], [-36, 0]);

  const cardProgress = spring({ frame, fps: vfps, delay: 20, config: { damping: 200 } });
  const cardY = interpolate(cardProgress, [0, 1], [50, 0]);

  const badgeProgress = spring({ frame, fps: vfps, delay: 140, config: { damping: 200 } });
  const badgeScale = interpolate(badgeProgress, [0, 1], [0.88, 1]);

  return (
    <AbsoluteFill
      style={{
        fontFamily: "sans-serif",
        background: `radial-gradient(ellipse at 25% 20%, rgba(82,143,255,0.1) 0%, ${COLORS.bg} 55%)`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div style={{ width: 3200, display: "flex", flexDirection: "column", alignItems: "center", paddingBottom: 60 }}>

        {/* Title */}
        <div style={{ opacity: titleProgress, transform: `translateY(${titleY}px)`, marginBottom: 72, textAlign: "center" }}>
          <div style={{ fontSize: 26, fontWeight: 600, color: COLORS.muted, letterSpacing: "0.35em", textTransform: "uppercase" as const, marginBottom: 18 }}>
            STEP 01
          </div>
          <div style={{ fontSize: 68, fontWeight: 700, color: COLORS.accent, letterSpacing: "0.15em", textTransform: "uppercase" as const }}>
            BUILD A CREDIBILITY FILTER
          </div>
        </div>

        {/* Two-column layout */}
        <div style={{ display: "flex", gap: 56, width: "100%", alignItems: "flex-start" }}>

          {/* Left: Profile card */}
          <div
            style={{
              flex: "0 0 820px",
              backgroundColor: "rgba(255,255,255,0.03)",
              border: "1px solid rgba(255,255,255,0.07)",
              borderTop: `4px solid ${COLORS.accent}`,
              borderRadius: 24,
              padding: "44px 48px",
              opacity: cardProgress,
              transform: `translateY(${cardY}px)`,
            }}
          >
            {/* Profile header */}
            <div style={{ display: "flex", alignItems: "center", gap: 28, marginBottom: 36 }}>
              <div
                style={{
                  width: 88,
                  height: 88,
                  borderRadius: 44,
                  backgroundColor: "rgba(82,143,255,0.12)",
                  border: `2px solid rgba(82,143,255,0.3)`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: 40,
                }}
              >
                👤
              </div>
              <div>
                <div style={{ fontSize: 36, fontWeight: 700, color: COLORS.light }}>@berlin.lifestyle</div>
                <div style={{ fontSize: 24, fontWeight: 600, color: COLORS.muted, marginTop: 6, letterSpacing: "0.1em" }}>
                  ABOUT PROFILE FIELDS
                </div>
              </div>
            </div>

            <div style={{ height: 1, backgroundColor: "rgba(255,255,255,0.05)", marginBottom: 24 }} />

            {/* Rows */}
            {profileRows.map((row, i) => {
              const rp = spring({ frame, fps: vfps, delay: 38 + i * 10, config: { damping: 200 } });
              const rx = interpolate(rp, [0, 1], [30, 0]);
              return (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    padding: "18px 28px",
                    backgroundColor: i % 2 === 0 ? "rgba(255,255,255,0.025)" : "transparent",
                    borderRadius: 10,
                    opacity: rp,
                    transform: `translateX(${rx}px)`,
                    marginBottom: 4,
                  }}
                >
                  <div style={{ fontSize: 28, fontWeight: 600, color: COLORS.muted }}>{row.field}</div>
                  <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
                    <div style={{ fontSize: 30, fontWeight: 700, color: COLORS.light }}>{row.value}</div>
                    {row.risk && (
                      <div style={{ width: 10, height: 10, borderRadius: 5, backgroundColor: "#EF4444", boxShadow: "0 0 8px #EF4444" }} />
                    )}
                  </div>
                </div>
              );
            })}

            <div
              style={{
                marginTop: 32,
                display: "flex",
                alignItems: "center",
                gap: 14,
                backgroundColor: "rgba(82,143,255,0.06)",
                border: "1px solid rgba(82,143,255,0.15)",
                borderRadius: 14,
                padding: "18px 28px",
              }}
            >
              <div style={{ fontSize: 30 }}>📊</div>
              <div style={{ fontSize: 24, fontWeight: 600, color: COLORS.muted }}>
                Sort & filter in a spreadsheet · minutes not hours
              </div>
            </div>
          </div>

          {/* Right: Flags */}
          <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 24 }}>
            <div
              style={{
                fontSize: 26,
                fontWeight: 600,
                color: COLORS.muted,
                letterSpacing: "0.25em",
                textTransform: "uppercase" as const,
                marginBottom: 12,
                opacity: cardProgress,
              }}
            >
              RED FLAGS TO WATCH
            </div>
            {credibilityFlags.map((flag, i) => (
              <FlagRow key={i} item={flag} delay={45 + i * 18} />
            ))}
          </div>
        </div>

        {/* Badge */}
        <div
          style={{
            marginTop: 64,
            opacity: badgeProgress,
            transform: `scale(${badgeScale})`,
            backgroundColor: "rgba(82,143,255,0.08)",
            border: `1px solid ${COLORS.accent}`,
            borderRadius: 20,
            padding: "28px 64px",
            fontSize: 36,
            fontWeight: 700,
            color: COLORS.accent,
            letterSpacing: "0.12em",
            textTransform: "uppercase" as const,
          }}
        >
          🛡 FILTER RISKS BEFORE THEY HIT YOUR SHORTLIST
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ─── Scene 2: Automate Vetting Pipeline ────────────────────────────────────

const pipelineSteps = [
  { icon: "🕷️", label: "Scrape Profiles", sublabel: "Apify Actor", color: COLORS.accent },
  { icon: "📋", label: "Google Sheets", sublabel: "Auto-land data", color: "#22C55E" },
  { icon: "⚙️", label: "n8n / Zapier", sublabel: "Trigger logic", color: "#F5BC38" },
  { icon: "🔀", label: "Score & Route", sublabel: "Threshold filter", color: "#B482ED" },
];

const scoringCriteria = [
  { label: "Username Stability", weight: 30, color: COLORS.accent },
  { label: "Account Age", weight: 25, color: "#22C55E" },
  { label: "Location Match", weight: 25, color: "#F5BC38" },
  { label: "Verification", weight: 20, color: "#B482ED" },
];

const outcomes = [
  { icon: "✅", label: "Added to Outreach CRM", sublabel: "Score ≥ 70 → auto-enroll", color: "#22C55E" },
  { icon: "🚩", label: "Flagged for Manual Review", sublabel: "Score < 70 → human check", color: "#EF4444" },
  { icon: "🔁", label: "Runs Every Batch", sublabel: "Triggered on each scrape", color: COLORS.accent },
];

const SceneAutomatedPipeline: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const titleProgress = spring({ frame, fps: vfps, delay: 5, config: { damping: 200 } });
  const titleY = interpolate(titleProgress, [0, 1], [-36, 0]);

  const scoringCardProgress = spring({ frame, fps: vfps, delay: 22, config: { damping: 200 } });
  const scoringCardY = interpolate(scoringCardProgress, [0, 1], [50, 0]);

  const badgeProgress = spring({ frame, fps: vfps, delay: 155, config: { damping: 200 } });
  const badgeScale = interpolate(badgeProgress, [0, 1], [0.88, 1]);

  return (
    <AbsoluteFill
      style={{
        fontFamily: "sans-serif",
        background: `radial-gradient(ellipse at 70% 25%, rgba(82,143,255,0.1) 0%, ${COLORS.bg} 55%)`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div style={{ width: 3200, display: "flex", flexDirection: "column", alignItems: "center", paddingBottom: 60 }}>

        {/* Title */}
        <div style={{ opacity: titleProgress, transform: `translateY(${titleY}px)`, marginBottom: 64, textAlign: "center" }}>
          <div style={{ fontSize: 26, fontWeight: 600, color: COLORS.muted, letterSpacing: "0.35em", textTransform: "uppercase" as const, marginBottom: 18 }}>
            STEP 02
          </div>
          <div style={{ fontSize: 68, fontWeight: 700, color: COLORS.accent, letterSpacing: "0.15em", textTransform: "uppercase" as const }}>
            AUTOMATE YOUR VETTING PIPELINE
          </div>
        </div>

        {/* Pipeline row */}
        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 60, width: "100%" }}>
          {pipelineSteps.map((step, i) => {
            const np = spring({ frame, fps: vfps, delay: 22 + i * 16, config: { damping: 200 } });
            const ny = interpolate(np, [0, 1], [50, 0]);
            const ap = i < pipelineSteps.length - 1
              ? spring({ frame, fps: vfps, delay: 30 + i * 16, config: { damping: 200 } })
              : 0;

            return (
              <React.Fragment key={i}>
                {/* Node */}
                <div
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    gap: 18,
                    opacity: np,
                    transform: `translateY(${ny}px)`,
                  }}
                >
                  <div
                    style={{
                      width: 140,
                      height: 140,
                      borderRadius: 28,
                      backgroundColor: `${step.color}14`,
                      border: `2px solid ${step.color}40`,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      fontSize: 56,
                    }}
                  >
                    {step.icon}
                  </div>
                  <div style={{ textAlign: "center" }}>
                    <div style={{ fontSize: 28, fontWeight: 700, color: COLORS.light }}>{step.label}</div>
                    <div style={{ fontSize: 22, fontWeight: 600, color: COLORS.muted, marginTop: 6 }}>{step.sublabel}</div>
                  </div>
                  <div style={{ width: 40, height: 3, borderRadius: 2, backgroundColor: step.color, opacity: 0.5 }} />
                </div>

                {/* Arrow */}
                {i < pipelineSteps.length - 1 && (
                  <div style={{ display: "flex", alignItems: "center", opacity: ap, paddingBottom: 52, margin: "0 16px" }}>
                    <svg width="72" height="28" viewBox="0 0 72 28">
                      <line x1="4" y1="14" x2={4 + 50 * ap} y2="14" stroke={pipelineSteps[i + 1].color} strokeWidth="2" strokeLinecap="round" opacity={0.4} />
                      <path d="M54 7l10 7-10 7" stroke={pipelineSteps[i + 1].color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" fill="none" opacity={ap * 0.6} />
                    </svg>
                  </div>
                )}
              </React.Fragment>
            );
          })}
        </div>

        {/* Bottom section: scoring + outcomes */}
        <div style={{ display: "flex", gap: 48, width: "100%", alignItems: "flex-start" }}>

          {/* Scoring card */}
          <div
            style={{
              flex: "0 0 1060px",
              backgroundColor: "rgba(255,255,255,0.03)",
              border: "1px solid rgba(255,255,255,0.07)",
              borderTop: `4px solid ${COLORS.accent}`,
              borderRadius: 24,
              padding: "44px 48px",
              opacity: scoringCardProgress,
              transform: `translateY(${scoringCardY}px)`,
            }}
          >
            <div style={{ fontSize: 26, fontWeight: 600, color: COLORS.muted, letterSpacing: "0.22em", textTransform: "uppercase" as const, marginBottom: 32 }}>
              CREDIBILITY SCORE WEIGHTS
            </div>

            <div style={{ display: "flex", flexDirection: "column", gap: 26 }}>
              {scoringCriteria.map((item, i) => {
                const bp = spring({ frame, fps: vfps, delay: 80 + i * 14, config: { damping: 200 } });
                return (
                  <div key={i} style={{ display: "flex", alignItems: "center", gap: 24, opacity: bp }}>
                    <div style={{ width: 240, fontSize: 26, fontWeight: 600, color: COLORS.muted, textAlign: "right" }}>
                      {item.label}
                    </div>
                    <div style={{ flex: 1, height: 36, backgroundColor: "rgba(255,255,255,0.05)", borderRadius: 18, overflow: "hidden" }}>
                      <div
                        style={{
                          width: `${item.weight * bp}%`,
                          height: "100%",
                          backgroundColor: item.color,
                          borderRadius: 18,
                          opacity: 0.7,
                        }}
                      />
                    </div>
                    <div style={{ width: 72, fontSize: 28, fontWeight: 700, color: item.color }}>
                      {Math.round(item.weight * bp)}%
                    </div>
                  </div>
                );
              })}
            </div>

            <div style={{ height: 1, backgroundColor: "rgba(255,255,255,0.05)", margin: "36px 0 24px" }} />
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <div style={{ fontSize: 26, fontWeight: 600, color: COLORS.muted }}>Pass threshold</div>
              <div style={{ fontSize: 38, fontWeight: 700, color: COLORS.light }}>Score ≥ 70</div>
            </div>
          </div>

          {/* Outcomes */}
          <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 24 }}>
            <div style={{ fontSize: 26, fontWeight: 600, color: COLORS.muted, letterSpacing: "0.22em", textTransform: "uppercase" as const, marginBottom: 8, opacity: scoringCardProgress }}>
              AUTOMATED OUTCOMES
            </div>
            {outcomes.map((o, i) => {
              const op = spring({ frame, fps: vfps, delay: 95 + i * 18, config: { damping: 200 } });
              const ox = interpolate(op, [0, 1], [50, 0]);
              return (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 32,
                    backgroundColor: `${o.color}0C`,
                    border: `1px solid ${o.color}28`,
                    borderLeft: `4px solid ${o.color}`,
                    borderRadius: 20,
                    padding: "30px 40px",
                    opacity: op,
                    transform: `translateX(${ox}px)`,
                  }}
                >
                  <div style={{ fontSize: 44 }}>{o.icon}</div>
                  <div>
                    <div style={{ fontSize: 30, fontWeight: 700, color: o.color, marginBottom: 6 }}>{o.label}</div>
                    <div style={{ fontSize: 24, fontWeight: 600, color: COLORS.muted }}>{o.sublabel}</div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Badge */}
        <div
          style={{
            marginTop: 60,
            opacity: badgeProgress,
            transform: `scale(${badgeScale})`,
            backgroundColor: "rgba(82,143,255,0.07)",
            border: `1px solid ${COLORS.accent}`,
            borderRadius: 20,
            padding: "28px 64px",
            fontSize: 36,
            fontWeight: 700,
            color: COLORS.accent,
            letterSpacing: "0.12em",
            textTransform: "uppercase" as const,
          }}
        >
          🤖 MANUAL VETTING → AUTOMATED PIPELINE
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ─── Black Screen ───────────────────────────────────────────────────────────

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ─── Root ───────────────────────────────────────────────────────────────────

const SCENE_1_FRAMES = 360;
const SCENE_2_FRAMES = 370;

export default function InfluencerVettingVideo() {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={20}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition presentation={fade()} timing={linearTiming({ durationInFrames: 20 })} />

      <TransitionSeries.Sequence durationInFrames={SCENE_1_FRAMES + TRANSITION}>
        <SceneCredibilityFilter />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition presentation={fade()} timing={linearTiming({ durationInFrames: TRANSITION })} />

      <TransitionSeries.Sequence durationInFrames={SCENE_2_FRAMES + TRANSITION}>
        <SceneAutomatedPipeline />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition presentation={fade()} timing={linearTiming({ durationInFrames: 20 })} />

      <TransitionSeries.Sequence durationInFrames={25}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
}
